const bulbR = 0.82;
const neckR = 0.17;

function randomPointInFlask() {
  if (Math.random() < 0.82) {
    let p;
    do {
      p = new THREE.Vector3(
        (Math.random() * 2 - 1) * bulbR,
        (Math.random() * 2 - 1) * bulbR,
        (Math.random() * 2 - 1) * bulbR
      );
    } while (p.length() > bulbR);
    return p.add(bulbCenter);
  }
  const a = Math.random() * Math.PI * 2;
  const r = Math.sqrt(Math.random()) * neckR;
  return new THREE.Vector3(Math.cos(a) * r, 2.25 + Math.random() * 1.35, Math.sin(a) * r);
}

for (let i = 0; i < moleculeCount; i++) {
  const pos = randomPointInFlask();
