graph.add(makeLine([new THREE.Vector3(x0g, y0g, 0.02), new THREE.Vector3(x0g, y1g, 0.02)], 0x000000));

function graphPoint(T) {
  const P = P0 * T / T0;
  const x = x0g + (T - Tmin) / (Tmax - Tmin) * (x1g - x0g);
  const y = y0g + (P - 1.0) / (1.27 - 1.0) * (y1g - y0g);
