registerInteractive(ptLine, {
  title: 'P ∝ T',
  tooltip: 'Straight-line P–T relation',
  body: 'For a gas at constant volume and constant amount, pressure is directly proportional to absolute temperature in kelvin.'
});

const fixedMarkerMat = matBasic(0x888888, { side: THREE.DoubleSide });
for (const T of [Tmin, Tmed, Tmax]) {
  const m = new THREE.Mesh(new THREE.CircleGeometry(0.055, 24), fixedMarkerMat);
