}
const currentMarker = new THREE.Mesh(new THREE.CircleGeometry(0.085, 32), matBasic(0xff2100, { side: THREE.DoubleSide }));
currentMarker.position.copy(graphPoint(Tmin));
graph.add(currentMarker);

// Mini gauges.
const miniGaugeData = [
  { key: 'low', T: Tmin, x: 3.33, label: 'Low P' },
  { key: 'medium', T: Tmed, x: 4.45, label: 'Medium P' },
  { key: 'high', T: Tmax, x: 5.55, label: 'High P' }
];
const miniHighlights = {};
function angleForT(T) {
