function presetKeyFromT(T) {
  if (T < 314) return 'low';
  if (T < 353) return 'medium';
  return 'high';
}
function presetTemp(key) {
  return key === 'high' ? Tmax : key === 'medium' ? Tmed : Tmin;
}
function labelForKey(key) {
  if (key === 'high') return { title: 'High <i>P</i>', caption: 'Hot plate on high' };
  if (key === 'medium') return { title: 'Medium <i>P</i>', caption: 'Hot plate on medium' };
  return { title: 'Low <i>P</i>', caption: 'Hot plate off' };
}

function updateNeedle(T) {
  const a = angleForT(T);
  const end = new THREE.Vector3(Math.sin(a) * 0.43, -Math.cos(a) * 0.43, 0.09);
  needle.geometry.setFromPoints([new THREE.Vector3(0, 0, 0.09), end]);
}

function updateVisuals(T) {
  temperatureK = T;
  const key = presetKeyFromT(T);
  const heat = (T - Tmin) / (Tmax - Tmin);
  const boil = Math.max(0, (T - 318) / (Tmax - 318));
  const labels = labelForKey(key);

  titleLabel.div.innerHTML = labels.title;
  captionLabel.div.innerHTML = labels.caption;
  tempReadout.textContent = `${Math.round(T)} K`;
  tempSlider.value = String(Math.round(T));

  presetButtons.forEach(b => b.classList.toggle('active', b.dataset.preset === key));
  for (const k of Object.keys(miniHighlights)) {
    miniHighlights[k].material.opacity = k === key ? 0.95 : 0;
  }

  const ringColor = new THREE.Color(0x24302f);
  if (heat > 0.02) {
    const medium = new THREE.Color(0xf0782d);
    const high = new THREE.Color(0xff2100);
    ringColor.copy(medium).lerp(high, Math.max(0, (T - Tmed) / (Tmax - Tmed)));
  }
  heatingRingMat.color.copy(ringColor);
  heatingRingMat.opacity = heat > 0.02 ? 0.95 : 0.7;
  indicator.material.color.set(heat > 0.02 ? 0xdd2b2b : 0x1f2828);

  const waterSurface = 1.75 + heat * (2.9 - 1.75);
  const waterBottom = 0.72;
  water.scale.set(1, Math.max(0.05, waterSurface - waterBottom), 1);
  water.position.set(0, (waterSurface + waterBottom) / 2, 0);
  water.material.opacity = 0.38 + heat * 0.16;

  updateNeedle(T);
  currentMarker.position.copy(graphPoint(T));

  steamLines.forEach((line, i) => {
    const maxCount = Math.round(2 + boil * 23);
    const mediumCount = Math.round(2 + Math.max(0, (T - 305) / (Tmax - 305)) * 23);
    const count = T < 314 ? Math.round(heat * 2) : Math.min(maxCount, mediumCount);
    line.visible = i < count;
    line.material.opacity = line.visible ? (0.25 + boil * 0.45) : 0;
  });
}

function updateBubbles(dt) {
  const boil = Math.max(0, (temperatureK - 318) / (Tmax - 318));
  const visibleCount = temperatureK < 314 ? 0 : Math.round(8 + boil * 82);
  const waterSurface = 1.75 + ((temperatureK - Tmin) / (Tmax - Tmin)) * (2.9 - 1.75);
  for (let i = 0; i < bubbleCount; i++) {
    const b = bubbles[i];
    if (i < visibleCount) {
      b.y += dt * (0.18 + boil * 0.75) * b.s;
      if (b.y > waterSurface - 0.05) b.y = 0.8 + Math.random() * 0.25;
      molDummy.position.set(b.x + Math.sin(performance.now() * 0.002 + b.phase) * 0.015, b.y, b.z);
      const sc = 0.7 + boil * 0.8 + Math.sin(performance.now() * 0.006 + b.phase) * 0.12;
      molDummy.scale.setScalar(sc);
    } else {
      molDummy.position.set(0, -20, 0);
      molDummy.scale.setScalar(0.001);
    }
    molDummy.updateMatrix();
    bubblesMesh.setMatrixAt(i, molDummy.matrix);
  }
  bubblesMesh.instanceMatrix.needsUpdate = true;
}

function simulateMolecules(dt) {
  const speedScale = Math.sqrt(temperatureK / T0);
  const step = dt * speedScale * 0.92;
  for (let i = 0; i < moleculeCount; i++) {
    const m = molecules[i];
    if (moleculesAnimating) m.pos.addScaledVector(m.vel, step);

    const inNeckRegion = m.pos.y > 2.18 && m.pos.y < 3.66;
    const radial = Math.hypot(m.pos.x, m.pos.z);

    if (inNeckRegion && radial < neckR * 1.8) {
      if (radial > neckR) {
        const n = new THREE.Vector3(m.pos.x, 0, m.pos.z).normalize();
        m.pos.x = n.x * neckR;
        m.pos.z = n.z * neckR;
        m.vel.reflect(n);
        addCollisionFlash(m.pos, n);
      }
      if (m.pos.y > 3.65) {
        m.pos.y = 3.65;
        m.vel.y *= -1;
        addCollisionFlash(m.pos, new THREE.Vector3(0, 1, 0));
      }
    } else {
      const rel = m.pos.clone().sub(bulbCenter);
      if (rel.length() > bulbR) {
        const n = rel.normalize();
        m.pos.copy(bulbCenter).addScaledVector(n, bulbR);
        m.vel.reflect(n);
        addCollisionFlash(m.pos, n);
      }
    }

    if (m.pos.y < 0.95) {
      m.pos.y = 0.95;
      m.vel.y = Math.abs(m.vel.y);
    }

    molDummy.position.copy(m.pos);
    molDummy.scale.setScalar(1);
    molDummy.updateMatrix();
    moleculeMesh.setMatrixAt(i, molDummy.matrix);
  }
  moleculeMesh.instanceMatrix.needsUpdate = true;

  for (const f of flashes) {
    if (f.life > 0) {
      f.life -= dt * (1.8 + (temperatureK - Tmin) / (Tmax - Tmin));
      f.line.material.opacity = Math.max(0, f.life);
    }
  }
}

let tween = null;
function setTemperature(T) {
  updateVisuals(THREE.MathUtils.clamp(T, Tmin, Tmax));
}

function tweenTemperature(targetT, duration = 650) {
  tween = { start: temperatureK, target: targetT, t0: performance.now(), duration };
}

function goToStep(i) {
  const step = demoSteps[i];
  if (!step) return;
  narration.innerHTML = `<b>${step.title}</b><br>${step.narration}`;
  tweenTemperature(step.state.temperature, 700);
}
