function figureTick(now) {
  requestAnimationFrame(figureTick);
  const dt = Math.min(0.05, (now - lastSim) / 1000);
  lastSim = now;

  if (tween) {
    const u = Math.min(1, (now - tween.t0) / tween.duration);
    const eased = u < 0.5 ? 2 * u * u : 1 - Math.pow(-2 * u + 2, 2) / 2;
    setTemperature(THREE.MathUtils.lerp(tween.start, tween.target, eased));
