// @FIGURE_CODE_BEGIN
// comparison panels → three Group objects laid out left-to-right in a flat frontal orthographic view
// hot plate top → flat trapezoid ShapeGeometry, muted green-gray
// hot plate front → BoxGeometry rectangular face with two dark feet and small switch/light
// heating element → flattened TorusGeometry ellipse on top plate, gray/orange/red by state
// beaker glass wall → transparent PlaneGeometry body with TorusGeometry top and bottom ellipses plus vertical Line sides
// water bath → transparent PlaneGeometry fill with cyan top ellipse; low/medium/high water levels
// round-bottom flask bulb → transparent CircleGeometry disk plus TorusGeometry outline
// flask neck → transparent BoxGeometry tube with two vertical Line outlines
// stopper/collar → short brown BoxGeometry and black TorusGeometry gasket
// pressure gauge → CircleGeometry face with two TorusGeometry rims, pivot dot, and Line needle at low/medium/high angle
// gas molecules → InstancedMesh small SphereGeometry dots moving inside each bulb/neck
// water bubbles → InstancedMesh small transparent SphereGeometry bubbles rising in medium/high baths
// steam wisps → pale cyan CatmullRomCurve3 Line objects above heated beakers
// labels → addLabel titles “Low P”, “Medium P”, “High P”, “Gas”, and hot-plate captions

scene.add(new THREE.AmbientLight(0xffffff, 1.0));

const T_LOW = 295;
const T_MED = 333;
const T_HIGH = 373;
const T_MIN = 295;
const T_MAX = 373;
let markerTemperature = T_LOW;
let moleculesAnimating = true;

const root = new THREE.Group();
scene.add(root);

function matBasic(color, opts = {}) {
  return new THREE.MeshBasicMaterial({
    color,
    transparent: !!opts.transparent,
    opacity: opts.opacity ?? 1,
    side: opts.side ?? THREE.FrontSide,
    depthWrite: opts.depthWrite ?? !opts.transparent
  });
}

function makeLine(points, color = 0x000000, opts = {}) {
  const geom = new THREE.BufferGeometry().setFromPoints(points);
  const mat = new THREE.LineBasicMaterial({
    color,
    transparent: !!opts.transparent,
    opacity: opts.opacity ?? 1,
    depthWrite: opts.depthWrite ?? !opts.transparent
  });
  return new THREE.Line(geom, mat);
}

function makeEllipseLine(rx, ry, color, opts = {}) {
  const pts = [];
  const n = opts.segments || 96;
  const z = opts.z ?? 0;
  for (let i = 0; i <= n; i++) {
    const a = (i / n) * Math.PI * 2;
    pts.push(new THREE.Vector3(Math.cos(a) * rx, Math.sin(a) * ry, z));
  }
  return makeLine(pts, color, opts);
}

function makePoly(points, color, opts = {}) {
  const shape = new THREE.Shape(points.map(p => new THREE.Vector2(p[0], p[1])));
  const mesh = new THREE.Mesh(new THREE.ShapeGeometry(shape), matBasic(color, {
    transparent: !!opts.transparent,
    opacity: opts.opacity ?? 1,
    side: THREE.DoubleSide,
    depthWrite: opts.depthWrite ?? false
  }));
  mesh.position.z = opts.z ?? 0;
  return mesh;
}

function addRect(group, w, h, x, y, z, color, opts = {}) {
  const mesh = new THREE.Mesh(
    new THREE.BoxGeometry(w, h, opts.depth ?? 0.018),
    matBasic(color, {
      transparent: !!opts.transparent,
      opacity: opts.opacity ?? 1,
      side: THREE.DoubleSide,
      depthWrite: opts.depthWrite ?? false
    })
  );
  mesh.position.set(x, y, z);
  group.add(mesh);
  return mesh;
}

function gaugeNeedleAngleForState(key) {
  if (key === 'high') return { tip: new THREE.Vector3(0.24, 0.05, 0.22), pivot: new THREE.Vector3(0, -0.19, 0.22) };
  if (key === 'medium') return { tip: new THREE.Vector3(0, 0.26, 0.22), pivot: new THREE.Vector3(0, -0.19, 0.22) };
  return { tip: new THREE.Vector3(-0.24, 0.05, 0.22), pivot: new THREE.Vector3(0, -0.19, 0.22) };
}

const panelSpecs = [
  { key: 'low', x: -3.15, title: 'Low <i>P</i>', caption: 'Hot plate off', T: T_LOW, heatColor: 0x819997, heatOpacity: 0.24, waterLevel: 0.91, gasCount: 14, bubbleCount: 0, steamCount: 0 },
  { key: 'medium', x: 0, title: 'Medium <i>P</i>', caption: 'Hot plate on medium', T: T_MED, heatColor: 0xf06f3a, heatOpacity: 0.78, waterLevel: 1.16, gasCount: 27, bubbleCount: 18, steamCount: 11 },
  { key: 'high', x: 3.15, title: 'High <i>P</i>', caption: 'Hot plate on high', T: T_HIGH, heatColor: 0xff2200, heatOpacity: 0.96, waterLevel: 1.47, gasCount: 46, bubbleCount: 78, steamCount: 22 }
];

const panels = [];
const molDummy = new THREE.Object3D();

// invisible framing guide for the wide three-panel textbook layout
const bounds = new THREE.Line(
  new THREE.BufferGeometry().setFromPoints([
    new THREE.Vector3(-4.65, -0.68, 0),
    new THREE.Vector3(4.65, 2.96, 0)
  ]),
  new THREE.LineBasicMaterial({ color: 0xffffff, transparent: true, opacity: 0 })
);
root.add(bounds);

function randomPointInGas() {
  const bulbCenter = new THREE.Vector2(0, 0.98);
  const bulbR = 0.43;
  const neckX = 0.105;
  if (Math.random() < 0.84) {
    let p;
    do {
      p = new THREE.Vector2((Math.random() * 2 - 1) * bulbR, (Math.random() * 2 - 1) * bulbR);
    } while (p.length() > bulbR);
    return new THREE.Vector3(p.x + bulbCenter.x, p.y + bulbCenter.y, 0.22);
  }
  return new THREE.Vector3((Math.random() * 2 - 1) * neckX, 1.36 + Math.random() * 0.63, 0.22);
}

function randomBubble(waterLevel) {
  return {
    x: (Math.random() * 2 - 1) * 0.58,
    y: 0.36 + Math.random() * Math.max(0.1, waterLevel - 0.38),
    s: 0.65 + Math.random() * 0.9,
    phase: Math.random() * Math.PI * 2
  };
}

function buildPanel(spec) {
  const g = new THREE.Group();
  g.position.x = spec.x;
  root.add(g);

  const panel = { spec, group: g, molecules: [], bubbles: [], steam: [] };

  // Hot plate body.
  const top = makePoly(
    [[-1.24, 0.02], [1.24, 0.02], [1.08, 0.46], [-1.08, 0.46]],
    0x6d807e,
    { z: -0.06 }
  );
  g.add(top);

  const front = addRect(g, 2.44, 0.34, 0, -0.12, -0.04, 0x435553, { depth: 0.03 });
  addRect(g, 0.24, 0.18, -0.92, -0.40, -0.03, 0x2f3d3b, { depth: 0.03 });
  addRect(g, 0.24, 0.18, 0.92, -0.40, -0.03, 0x2f3d3b, { depth: 0.03 });

  const switchBase = addRect(g, 0.105, 0.058, 0.98, -0.12, 0.06, 0x263231, { depth: 0.02 });
  const lightColor = spec.key === 'low' ? 0x2b3333 : 0xd93636;
  addRect(g, 0.072, 0.045, 1.055, -0.12, 0.08, lightColor, { depth: 0.02 });

  const ringMat = matBasic(spec.heatColor, { transparent: true, opacity: spec.heatOpacity, depthWrite: false });
  const heater = new THREE.Mesh(new THREE.TorusGeometry(0.62, 0.045, 14, 96), ringMat);
  heater.scale.y = 0.20;
  heater.position.set(0, 0.42, 0.07);
  g.add(heater);

  // Beaker and water bath.
  const beakerWall = new THREE.Mesh(
    new THREE.PlaneGeometry(1.42, 1.20),
    matBasic(0xd9fbfa, { transparent: true, opacity: 0.34, side: THREE.DoubleSide, depthWrite: false })
  );
  beakerWall.position.set(0, 0.93, 0.09);
  g.add(beakerWall);

  const waterH = spec.waterLevel - 0.34;
  const water = new THREE.Mesh(
    new THREE.PlaneGeometry(1.28, Math.max(0.05, waterH)),
    matBasic(0x77eee7, { transparent: true, opacity: spec.key === 'high' ? 0.58 : 0.48, side: THREE.DoubleSide, depthWrite: false })
  );
  water.position.set(0, 0.34 + waterH / 2, 0.12);
  g.add(water);

  const waterTop = makeEllipseLine(0.64, 0.075, 0x87efe8, { transparent: true, opacity: 0.72, z: 0.15 });
  waterTop.position.y = spec.waterLevel;
  g.add(waterTop);

  const rimMat = matBasic(0xb8e7e4, { transparent: true, opacity: 0.82, depthWrite: false });
  const topRim = new THREE.Mesh(new THREE.TorusGeometry(0.72, 0.026, 10, 96), rimMat);
  topRim.scale.y = 0.16;
  topRim.position.set(0, 1.56, 0.20);
  g.add(topRim);

  const bottomRim = new THREE.Mesh(new THREE.TorusGeometry(0.62, 0.018, 8, 96), matBasic(0xa7d9d6, { transparent: true, opacity: 0.70, depthWrite: false }));
  bottomRim.scale.y = 0.15;
  bottomRim.position.set(0, 0.34, 0.20);
  g.add(bottomRim);

  g.add(makeLine([new THREE.Vector3(-0.69, 0.36, 0.19), new THREE.Vector3(-0.69, 1.54, 0.19)], 0x9ccccc, { transparent: true, opacity: 0.74 }));
  g.add(makeLine([new THREE.Vector3(0.69, 0.36, 0.19), new THREE.Vector3(0.69, 1.54, 0.19)], 0x9ccccc, { transparent: true, opacity: 0.74 }));

  // Sealed flask.
  const bulb = new THREE.Mesh(
    new THREE.CircleGeometry(0.45, 72),
    matBasic(spec.key === 'high' ? 0xd6c5e8 : 0xdcdaf4, { transparent: true, opacity: 0.46, side: THREE.DoubleSide, depthWrite: false })
  );
  bulb.position.set(0, 0.96, 0.14);
  g.add(bulb);

  const bulbOutline = new THREE.Mesh(
    new THREE.TorusGeometry(0.455, 0.018, 8, 96),
    matBasic(0x9aa5a5, { transparent: true, opacity: 0.76, depthWrite: false })
  );
  bulbOutline.position.set(0, 0.96, 0.23);
  g.add(bulbOutline);

  const neckFill = addRect(g, 0.21, 0.74, 0, 1.65, 0.13, spec.key === 'high' ? 0xd6c5e8 : 0xdcdaf4, {
    transparent: true,
    opacity: 0.42,
    depth: 0.015
  });
  g.add(makeLine([new THREE.Vector3(-0.105, 1.29, 0.23), new THREE.Vector3(-0.105, 2.02, 0.23)], 0x9aa5a5, { transparent: true, opacity: 0.78 }));
  g.add(makeLine([new THREE.Vector3(0.105, 1.29, 0.23), new THREE.Vector3(0.105, 2.02, 0.23)], 0x9aa5a5, { transparent: true, opacity: 0.78 }));

  const collar = addRect(g, 0.29, 0.095, 0, 1.89, 0.26, 0xb7652d, { depth: 0.025 });
  const gasket = new THREE.Mesh(new THREE.TorusGeometry(0.155, 0.024, 8, 48), matBasic(0x1b1b1b, { depthWrite: false }));
  gasket.scale.y = 0.30;
  gasket.position.set(0, 1.95, 0.27);
  g.add(gasket);

  // Gauge.
  const gauge = new THREE.Group();
  gauge.position.set(0, 2.34, 0.23);
  g.add(gauge);

  const gaugeFace = new THREE.Mesh(new THREE.CircleGeometry(0.32, 72), matBasic(0xffffff, { side: THREE.DoubleSide }));
  gaugeFace.position.z = 0.015;
  gauge.add(gaugeFace);

  const outerRim = new THREE.Mesh(new THREE.TorusGeometry(0.345, 0.038, 14, 96), matBasic(0x303437));
  outerRim.position.z = 0.035;
  gauge.add(outerRim);

  const innerRim = new THREE.Mesh(new THREE.TorusGeometry(0.303, 0.014, 8, 96), matBasic(0x66696a));
  innerRim.position.z = 0.055;
  gauge.add(innerRim);

  const nd = gaugeNeedleAngleForState(spec.key);
  const needle = makeLine([nd.pivot, nd.tip], 0x000000);
  needle.position.z = 0.065;
  gauge.add(needle);

  const pivot = new THREE.Mesh(new THREE.CircleGeometry(0.035, 24), matBasic(0x000000, { side: THREE.DoubleSide }));
  pivot.position.set(nd.pivot.x, nd.pivot.y, 0.12);
  gauge.add(pivot);

  const connector = addRect(g, 0.105, 0.26, 0, 2.03, 0.19, 0x8e9696, { transparent: true, opacity: 0.82, depth: 0.02 });

  // Gas molecules.
  const gasGeom = new THREE.SphereGeometry(0.019, 10, 8);
  const gasMat = new THREE.MeshBasicMaterial({ color: 0x63b7d8, transparent: true, opacity: 0.70, depthWrite: false });
  const gasMesh = new THREE.InstancedMesh(gasGeom, gasMat, spec.gasCount);
  gasMesh.instanceMatrix.setUsage(THREE.DynamicDrawUsage);
  g.add(gasMesh);
  panel.gasMesh = gasMesh;

  for (let i = 0; i < spec.gasCount; i++) {
    const pos = randomPointInGas();
    const vel = new THREE.Vector3(Math.random() - 0.5, Math.random() - 0.5, 0).normalize().multiplyScalar(0.22 + Math.random() * 0.18);
    panel.molecules.push({ pos, vel });
    molDummy.position.copy(pos);
    molDummy.scale.setScalar(1);
    molDummy.updateMatrix();
    gasMesh.setMatrixAt(i, molDummy.matrix);
  }
  gasMesh.instanceMatrix.needsUpdate = true;

  // Bubbles.
  const bubbleGeom = new THREE.SphereGeometry(0.018, 8, 6);
  const bubbleMat = new THREE.MeshBasicMaterial({ color: 0xdbffff, transparent: true, opacity: spec.key === 'high' ? 0.78 : 0.58, depthWrite: false });
  const bubbleMesh = new THREE.InstancedMesh(bubbleGeom, bubbleMat, Math.max(1, spec.bubbleCount));
  bubbleMesh.instanceMatrix.setUsage(THREE.DynamicDrawUsage);
  g.add(bubbleMesh);
  panel.bubbleMesh = bubbleMesh;

  for (let i = 0; i < Math.max(1, spec.bubbleCount); i++) {
    const b = randomBubble(spec.waterLevel);
    panel.bubbles.push(b);
    molDummy.position.set(spec.bubbleCount ? b.x : 0, spec.bubbleCount ? b.y : -20, 0.24);
    molDummy.scale.setScalar(spec.bubbleCount ? b.s : 0.001);
    molDummy.updateMatrix();
    bubbleMesh.setMatrixAt(i, molDummy.matrix);
  }
  bubbleMesh.instanceMatrix.needsUpdate = true;

  // Steam.
  for (let i = 0; i < spec.steamCount; i++) {
    const x = -0.57 + Math.random() * 1.14;
    const y0 = 1.67 + Math.random() * 0.08;
    const h = spec.key === 'high' ? 0.36 + Math.random() * 0.28 : 0.27 + Math.random() * 0.18;
    const sway = (Math.random() - 0.5) * 0.18;
    const curve = new THREE.CatmullRomCurve3([
      new THREE.Vector3(x, y0, 0.18),
      new THREE.Vector3(x + sway * 0.35, y0 + h * 0.34, 0.18),
      new THREE.Vector3(x - sway * 0.25, y0 + h * 0.67, 0.18),
      new THREE.Vector3(x + sway, y0 + h, 0.18)
    ]);
    const steam = makeLine(curve.getPoints(20), 0x9ff7ef, {
      transparent: true,
      opacity: spec.key === 'high' ? 0.66 : 0.48,
      depthWrite: false
    });
    steam.userData.phase = Math.random() * Math.PI * 2;
    g.add(steam);
    panel.steam.push(steam);
  }

  registerInteractive(outerRim, {
    title: `${spec.title.replace(/<[^>]*>/g, '')} gauge`,
    tooltip: 'Pressure reading',
    body: `This gauge shows the ${spec.key} pressure reading. With fixed volume and fixed amount of gas, the pressure rises as the absolute temperature rises.`
  });
  registerInteractive(bulb, {
    title: 'Sealed rigid flask',
    tooltip: 'Constant volume gas',
    body: 'The gas is sealed inside the flask. Since the flask volume does not change, faster molecular motion from heating produces greater pressure.'
  });
  registerInteractive(heater, {
    title: spec.caption,
    tooltip: 'Hot plate setting',
    body: spec.key === 'low'
      ? 'With the hot plate off, the water bath is coolest and the gas pressure is lowest.'
      : spec.key === 'medium'
        ? 'Medium heating warms the water bath and raises the pressure gauge to a middle reading.'
        : 'High heating makes the bath boil vigorously; molecule collisions are fastest and the pressure gauge reads highest.'
  });

  panel.heater = heater;
  panel.top = top;
  panel.front = front;
  panels.push(panel);
}

panelSpecs.forEach(buildPanel);

setCameraView({
  projection: 'orthographic',
  axisScreenAngles: null,
  target: [0, 1.12, 0],
  heightFraction: 0.88,
  distanceScale: 1.05
});

const titleLabels = {};
const captionLabels = {};
for (const spec of panelSpecs) {
  titleLabels[spec.key] = addLabel(spec.title, new THREE.Vector3(spec.x, 2.86, 0), {
    fontSize: '24px',
    color: '#000'
  });
  addLabel('Gas', new THREE.Vector3(spec.x, 0.97, 0.3), {
    fontSize: '23px',
    color: '#000'
  });
  captionLabels[spec.key] = addLabel(spec.caption, new THREE.Vector3(spec.x, -0.58, 0), {
    fontSize: '23px',
    color: '#000'
  });
}

const tempSlider = document.getElementById('temperature');
const tempReadout = document.getElementById('tempReadout');
const animCheck = document.getElementById('gasMoleculeMotion');
const narration = document.getElementById('stepNarration');
const presetButtons = Array.from(document.querySelectorAll('#heatingPreset button'));

const demoSteps = [
  {
    key: 'low',
    T: T_LOW,
    title: 'Low pressure: hot plate off',
    narration: 'The bath is cool, the heating element is dark, gas molecules move relatively slowly, and the gauge reads low pressure.'
  },
  {
    key: 'medium',
    T: T_MED,
    title: 'Medium pressure: moderate heating',
    narration: 'Heating the bath increases molecular speed. The sealed flask volume is unchanged, so the gauge needle moves to a medium pressure.'
  },
  {
    key: 'high',
    T: T_HIGH,
    title: 'High pressure: strong heating',
    narration: 'At high temperature the bath boils and the gas molecules collide rapidly with the rigid flask walls, giving the highest pressure reading.'
  }
];

function keyFromTemperature(T) {
  if (T < 314) return 'low';
  if (T < 353) return 'medium';
  return 'high';
}

function tempForKey(key) {
  return key === 'high' ? T_HIGH : key === 'medium' ? T_MED : T_LOW;
}

function updateUiState(T, narrate = false) {
  markerTemperature = THREE.MathUtils.clamp(T, T_MIN, T_MAX);
  const key = keyFromTemperature(markerTemperature);
  tempSlider.value = String(Math.round(markerTemperature));
  tempReadout.textContent = `${Math.round(markerTemperature)} K`;

  presetButtons.forEach(btn => btn.classList.toggle('active', btn.dataset.preset === key));

  for (const p of panels) {
    const active = p.spec.key === key;
    p.heater.scale.set(active ? 1.04 : 1.0, active ? 0.215 : 0.20, 1);
    titleLabels[p.spec.key].div.style.fontWeight = active ? '700' : '400';
  }

  if (narrate) {
    const step = demoSteps.find(s => s.key === key);
    narration.innerHTML = `<b>${step.title}</b><br>${step.narration}`;
  }
}

function goToStep(i) {
  const step = demoSteps[i];
  if (!step) return;
  updateUiState(step.T, true);
}
window.goToStep = goToStep;

presetButtons.forEach(btn => {
  btn.addEventListener('click', () => {
