function keyFromTemperature(T) {
  if (T < 314) return 'low';
  if (T < 353) return 'medium';
  return 'high';
}

function tempForKey(key) {
  return key === 'high' ? T_HIGH : key === 'medium' ? T_MED : T_LOW;
}

function updateUiState(T, narrate = false) {
  markerTemperature = THREE.MathUtils.clamp(T, T_MIN, T_MAX);
  const key = keyFromTemperature(markerTemperature);
  tempSlider.value = String(Math.round(markerTemperature));
  tempReadout.textContent = `${Math.round(markerTemperature)} K`;

  presetButtons.forEach(btn => btn.classList.toggle('active', btn.dataset.preset === key));

  for (const p of panels) {
    const active = p.spec.key === key;
    p.heater.scale.set(active ? 1.04 : 1.0, active ? 0.215 : 0.20, 1);
    titleLabels[p.spec.key].div.style.fontWeight = active ? '700' : '400';
  }

  if (narrate) {
    const step = demoSteps.find(s => s.key === key);
    narration.innerHTML = `<b>${step.title}</b><br>${step.narration}`;
  }
}

function goToStep(i) {
  const step = demoSteps[i];
  if (!step) return;
  updateUiState(step.T, true);
}
