function constrainGasParticle(m) {
  const bulbCenter = new THREE.Vector3(0, 0.96, 0.22);
  const bulbR = 0.43;
  const neckHalf = 0.095;
  const neckMinY = 1.34;
  const neckMaxY = 2.00;

  const inNeckBand = m.pos.y >= neckMinY && m.pos.y <= neckMaxY && Math.abs(m.pos.x) < neckHalf * 1.8;
  if (inNeckBand && m.pos.y > 1.34) {
    if (Math.abs(m.pos.x) > neckHalf) {
      m.pos.x = Math.sign(m.pos.x) * neckHalf;
      m.vel.x *= -1;
    }
    if (m.pos.y > neckMaxY) {
      m.pos.y = neckMaxY;
      m.vel.y *= -1;
    }
  } else {
    const rel = m.pos.clone().sub(bulbCenter);
    rel.z = 0;
    const len = Math.hypot(rel.x, rel.y);
    if (len > bulbR) {
      const nx = rel.x / len;
      const ny = rel.y / len;
      m.pos.x = bulbCenter.x + nx * bulbR;
      m.pos.y = bulbCenter.y + ny * bulbR;
      const dot = m.vel.x * nx + m.vel.y * ny;
      m.vel.x -= 2 * dot * nx;
      m.vel.y -= 2 * dot * ny;
    }
  }
}

let lastTick = performance.now();
function figureTick(now) {
  requestAnimationFrame(figureTick);
  const dt = Math.min(0.05, (now - lastTick) / 1000);
  lastTick = now;
  const time = now * 0.001;

  for (const panel of panels) {
    const tempSpeed = Math.sqrt(panel.spec.T / T_LOW);
    const extra = panel.spec.key === 'high' ? 1.42 : panel.spec.key === 'medium' ? 1.12 : 0.82;

    for (let i = 0; i < panel.molecules.length; i++) {
      const m = panel.molecules[i];
      if (moleculesAnimating) {
        m.pos.x += m.vel.x * dt * tempSpeed * extra;
        m.pos.y += m.vel.y * dt * tempSpeed * extra;
        constrainGasParticle(m);
      }
      molDummy.position.copy(m.pos);
      molDummy.scale.setScalar(1 + 0.08 * Math.sin(time * 5 + i));
      molDummy.updateMatrix();
      panel.gasMesh.setMatrixAt(i, molDummy.matrix);
    }
    panel.gasMesh.instanceMatrix.needsUpdate = true;

    for (let i = 0; i < panel.bubbles.length; i++) {
      const b = panel.bubbles[i];
      if (panel.spec.bubbleCount && moleculesAnimating) {
        b.y += dt * (panel.spec.key === 'high' ? 0.42 : 0.22) * b.s;
        if (b.y > panel.spec.waterLevel - 0.03) {
          b.y = 0.38 + Math.random() * 0.10;
          b.x = (Math.random() * 2 - 1) * 0.58;
        }
      }
      const visible = i < panel.spec.bubbleCount;
      molDummy.position.set(
        visible ? b.x + Math.sin(time * 2.4 + b.phase) * 0.012 : 0,
        visible ? b.y : -20,
        0.245
      );
      molDummy.scale.setScalar(visible ? b.s * (0.8 + 0.12 * Math.sin(time * 5 + b.phase)) : 0.001);
      molDummy.updateMatrix();
      panel.bubbleMesh.setMatrixAt(i, molDummy.matrix);
    }
    panel.bubbleMesh.instanceMatrix.needsUpdate = true;

    panel.steam.forEach((line, i) => {
      line.position.x = Math.sin(time * 1.2 + line.userData.phase) * 0.018;
      line.position.y = Math.sin(time * 1.7 + i) * 0.012;
      line.material.opacity = (panel.spec.key === 'high' ? 0.62 : 0.44) * (0.86 + 0.14 * Math.sin(time * 2 + i));
    });
  }
}
