function setNeedle(panel, T) {
  const f = temp01(T);
  const angle = THREE.MathUtils.degToRad(135 - 90 * f);
  const pivot = new THREE.Vector3(0, -0.19, 0.22);
  const tip = new THREE.Vector3(Math.cos(angle) * 0.33, pivot.y + Math.sin(angle) * 0.33, 0.22);
  panel.needle.geometry.dispose();
  panel.needle.geometry = new THREE.BufferGeometry().setFromPoints([pivot, tip]);
}

