function keyFromTemperature(T) {
  if (T < 314) return 'low';
  if (T < 353) return 'medium';
  return 'high';
}

function tempForKey(key) {
  return key === 'high' ? T_HIGH : key === 'medium' ? T_MED : T_LOW;
}

function updatePanelVisual(panel, T, active) {
  const s = stateFromT(T);
  panel.currentT = T;
  panel.visibleGas = s.gasCount;
  panel.visibleBubbles = s.bubbleCount;
  panel.visibleSteam = s.steamCount;
  panel.speedFactor = s.speed;

  const heatColor = new THREE.Color().setHSL(0.03, 1.0, THREE.MathUtils.lerp(0.36, 0.52, s.heat));
  panel.heater.material.color.copy(s.heat < 0.08 ? new THREE.Color(0x819997) : heatColor);
  panel.heater.material.opacity = THREE.MathUtils.lerp(0.23, 0.98, s.heat);
  panel.heater.scale.set(active ? 1.06 : 1.0, THREE.MathUtils.lerp(0.20, 0.23, s.heat), 1);

  panel.light.material.color.set(s.heat < 0.16 ? 0x2b3333 : 0xd93636);

  const waterH = Math.max(0.05, s.waterLevel - 0.35);
  panel.waterFill.scale.set(1, waterH, 1);
  panel.waterFill.position.y = 0.35;
  panel.waterTop.position.y = s.waterLevel;
  panel.waterFill.material.opacity = THREE.MathUtils.lerp(0.45, 0.64, s.heat);

  const tint = new THREE.Color(0xdcdaf4).lerp(new THREE.Color(0xd2b8e8), s.heat);
  panel.bulb.material.color.copy(tint);
  panel.neckFill.material.color.copy(tint);
  panel.bulb.material.opacity = THREE.MathUtils.lerp(0.42, 0.50, s.heat);

  panel.gasMesh.material.opacity = active ? 0.88 : 0.72;
  panel.bubbleMesh.material.opacity = THREE.MathUtils.lerp(0.45, 0.82, s.heat);
  setNeedle(panel, T);

  panel.group.scale.setScalar(active ? 1.035 : 1.0);
}

function updateUiState(T, narrate = false) {
  markerTemperature = THREE.MathUtils.clamp(T, T_MIN, T_MAX);
  const key = keyFromTemperature(markerTemperature);
  tempSlider.value = String(Math.round(markerTemperature));
  tempReadout.textContent = `${Math.round(markerTemperature)} K`;

  presetButtons.forEach(btn => btn.classList.toggle('active', btn.dataset.preset === key));

  for (const p of panels) {
    const active = p.spec.key === key;
    updatePanelVisual(p, active ? markerTemperature : p.spec.T, active);
    titleLabels[p.spec.key].div.style.fontWeight = active ? '700' : '400';
    captionLabels[p.spec.key].div.style.fontWeight = active ? '700' : '400';
    gasLabels[p.spec.key].div.style.fontWeight = active ? '700' : '400';
  }

  if (narrate) {
    const step = demoSteps.find(s => s.key === key);
    narration.innerHTML = `<b>${step.title}</b><br>${step.narration}`;
  }
}

function goToStep(i) {
  const step = demoSteps[i];
  if (!step) return;
  updateUiState(step.T, true);
}

