function constrainGasParticle(m) {
  const bulbCenter = new THREE.Vector3(0, 0.96, 0.24);
  const bulbR = 0.43;
  const neckHalf = 0.095;
  const neckMinY = 1.34;
  const neckMaxY = 2.00;

  const nearNeck = m.pos.y >= neckMinY && m.pos.y <= neckMaxY && Math.abs(m.pos.x) < neckHalf * 1.9;
  if (nearNeck && m.pos.y > 1.34) {
    if (Math.abs(m.pos.x) > neckHalf) {
      m.pos.x = Math.sign(m.pos.x) * neckHalf;
      m.vel.x *= -1;
    }
    if (m.pos.y > neckMaxY) {
      m.pos.y = neckMaxY;
      m.vel.y *= -1;
    }
  } else {
    const rel = m.pos.clone().sub(bulbCenter);
    rel.z = 0;
    const len = Math.hypot(rel.x, rel.y);
    if (len > bulbR) {
      const nx = rel.x / len;
      const ny = rel.y / len;
      m.pos.x = bulbCenter.x + nx * bulbR;
      m.pos.y = bulbCenter.y + ny * bulbR;
      const dot = m.vel.x * nx + m.vel.y * ny;
      m.vel.x -= 2 * dot * nx;
      m.vel.y -= 2 * dot * ny;
    }
  }
}

updateUiState(T_LOW, true);

let lastTick = performance.now();
function figureTick(now) {
  requestAnimationFrame(figureTick);
  const dt = Math.min(0.05, (now - lastTick) / 1000);
  lastTick = now;
  const time = now * 0.001;

  for (const panel of panels) {
    const s = stateFromT(panel.currentT);

    for (let i = 0; i < MAX_GAS; i++) {
      const m = panel.molecules[i];
      if (moleculesAnimating && i < panel.visibleGas) {
        m.pos.x += m.vel.x * dt * (panel.speedFactor || s.speed);
        m.pos.y += m.vel.y * dt * (panel.speedFactor || s.speed);
        constrainGasParticle(m);
      }
      if (i < panel.visibleGas) {
        molDummy.position.copy(m.pos);
        molDummy.scale.setScalar(s.moleculeScale * (1 + 0.08 * Math.sin(time * 5 + i)));
      } else {
        molDummy.position.set(0, -20, 0);
        molDummy.scale.setScalar(0.001);
      }
      molDummy.updateMatrix();
      panel.gasMesh.setMatrixAt(i, molDummy.matrix);
    }
    panel.gasMesh.instanceMatrix.needsUpdate = true;

    for (let i = 0; i < MAX_BUBBLES; i++) {
      const b = panel.bubbles[i];
      if (i < panel.visibleBubbles && moleculesAnimating) {
        b.y += dt * THREE.MathUtils.lerp(0.15, 0.50, s.heat) * b.s;
        if (b.y > s.waterLevel - 0.03) {
          b.y = 0.37 + Math.random() * 0.10;
          b.x = (Math.random() * 2 - 1) * 0.58;
        }
      }
      const visible = i < panel.visibleBubbles;
      molDummy.position.set(
        visible ? b.x + Math.sin(time * 2.4 + b.phase) * 0.012 : 0,
        visible ? b.y : -20,
        0.255
      );
      molDummy.scale.setScalar(visible ? b.s * (0.80 + 0.12 * Math.sin(time * 5 + b.phase)) : 0.001);
      molDummy.updateMatrix();
      panel.bubbleMesh.setMatrixAt(i, molDummy.matrix);
    }
    panel.bubbleMesh.instanceMatrix.needsUpdate = true;

    panel.steam.forEach((line, i) => {
      const visible = i < panel.visibleSteam;
      line.position.x = Math.sin(time * 1.2 + line.userData.phase) * 0.019;
      line.position.y = Math.sin(time * 1.7 + i) * 0.012;
      line.material.opacity = visible ? THREE.MathUtils.lerp(0.22, 0.68, s.heat) * (0.86 + 0.14 * Math.sin(time * 2 + i)) : 0;
    });
  }
}
requestAnimationFrame(figureTick);
